ic values in tables that could be employment\n# The values would be in thousands (like 125, 150, 175, etc.)\nfor i, elem in enumerate(data['document']['elements']):\n    if elem.get('type') == 'table':\n        content = elem.get('content', '')\n        # Look for tables with numbers in the employment/payroll range\n        if re.search(r'\\b[0-9]{2,3}\\b', content):  # 2-3 digit numbers\n            if any(x in content.lower() for x in ['2004', '2005', '2006']):\n                print(f\"Element {i}: Table with potential employment data\")\n                print(content[:800])\n                print(\"---\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
